<?php
echo '<div class="page-head"><div><h1>Repackaging Batches</h1><p>Group existing products for packaging work. This is a stock reclassification, not a new receipt.</p></div><a class="btn ghost" href="?page=nonsellable&stock_view=packaging">Non-Sellable Inventory</a></div>';
if(!repack_ready()){echo '<div class="alert warn">Run the Repackaging Batch upgrade first.</div>';if(current_user()['role']==='Admin')echo '<a class="btn primary" href="upgrade_repackaging_batch.php">Open Upgrade</a>';return;}
$owners=operational_users('import_orders');
function repack_fields($a,$id=0){echo '<input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($a).'"><input type="hidden" name="batch_id" value="'.(int)$id.'"><input type="hidden" name="return" value="repackaging_batch'.($id?'&id='.(int)$id:'').'">';}
if($id=(int)($_GET['id']??0)){
 try{$b=repack_batch($id);}catch(Throwable $ex){echo '<div class="alert danger">'.e($ex->getMessage()).'</div>';return;}
 echo '<a class="back" href="?page=repackaging_batch">← All Repackaging Batches</a><div class="card"><h2>'.e($b['batch_ref']).'</h2><p>'.e($b['source_name'].' · '.$b['reference_no'].' · '.$b['txn_date']).'</p><b>'.e($b['status']).'</b><p>'.e($b['reason']).'</p><p>Target: '.e($b['due_date']?:'Not set').'</p></div>';
 if($b['status']==='Review'){
  try{$a=repack_analysis($b);$fresh=hash_equals($a['digest'],$b['review_digest']);echo '<div class="card table-wrap"><h3>Review Product Lines</h3><table class="table"><tr><th>Product / SKU</th><th>Original Source</th><th>Qty</th><th>Classification</th><th>Platform Stock to Remove</th><th>Physical Effect</th></tr>';foreach($a['lines'] as $l){$moves=[];foreach($l['allocation'] as $pl=>$qty)if($qty)$moves[]=$pl.' '.$qty;echo '<tr><td>'.e($l['name']).'<br>'.e($l['master_sku']).'</td><td>'.e(($l['source_id']?'NS-'.$l['source_id'].' · ':'').$l['source_ref']).'</td><td>'.$l['qty'].' pcs</td><td>'.e($l['old_condition']).' → For Repackaging<br>'.e($l['mode']).'</td><td>'.e($moves?implode(' · ',$moves):'Unchanged').'</td><td>0 — unchanged</td></tr>';}echo '</table></div>';
  if(!$fresh)echo '<div class="alert warn">Stock or source details changed. Refresh Review, inspect the updated lines, then submit.</div>';
  if(can_action('repack_stage')){echo '<div class="card"><form method="post" action="actions.php" class="stack" data-confirm="Submit this existing-stock batch for repackaging? Physical total will remain unchanged. No new receipt is being recorded.">';repack_fields('repack_post',$id);echo '<input type="hidden" name="digest" value="'.e($a['digest']).'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed every source and quantity. These stocks are already recorded.</label><button class="btn primary" '.(!$fresh?'disabled':'').'>Submit Repackaging Batch</button></form><div class="modal-actions"><form method="post" action="actions.php">';repack_fields('repack_refresh',$id);echo '<button class="btn secondary">Refresh Review</button></form><form method="post" action="actions.php" data-confirm="Cancel this unposted batch? No inventory will change.">';repack_fields('repack_cancel',$id);echo '<button class="btn ghost">Cancel Batch</button></form></div></div>';}
  }catch(Throwable $ex){echo '<div class="alert danger">'.e($ex->getMessage()).' No stock has been posted by this review.</div>';if(can_action('repack_stage')){echo '<form method="post" action="actions.php">';repack_fields('repack_cancel',$id);echo '<button class="btn ghost">Cancel Batch</button></form>';}}
 }else{
  $q=db()->prepare('SELECT l.*,p.name,p.master_sku,n.packaging_state,n.condition_type,n.reversed_by_request,COALESCE((SELECT SUM(k.qty) FROM nonsellable_release_links k WHERE k.non_sellable_id=n.id),0) released FROM repackaging_batch_lines l JOIN products p ON p.id=l.product_id JOIN non_sellable n ON n.id=l.target_id WHERE l.batch_id=? ORDER BY l.line_no');$q->execute([$id]);echo '<div class="card table-wrap"><h3>Batch Items and Packaging Progress</h3><table class="table"><tr><th>Product / SKU</th><th>Source</th><th>Batch Qty</th><th>Remaining</th><th>Status</th><th>Action</th></tr>';foreach($q as $l){$remaining=max(0,(int)$l['qty']-max(0,(int)$l['released']-(int)$l['baseline_released']));echo '<tr><td>'.e($l['name']).'<br>'.e($l['master_sku']).'</td><td>'.($l['source_id']?'NS-'.(int)$l['source_id']:'Existing sellable stock').'</td><td>'.$l['qty'].' pcs</td><td>'.$remaining.' pcs</td><td>'.e($b['status']==='Reversed'?'Batch Reversed':($l['reversed_by_request']?'Source Reversed':($remaining?($l['packaging_state']?:'Pending'):'Completed / Released'))).'</td><td><a class="btn ghost sm" href="?page=packaging_detail&id='.(int)$l['target_id'].'">Manage / Ready for Sale</a></td></tr>';}echo '</table><p class="muted">Ready for Sale allows partial quantity per product and requires Admin approval with full platform allocation. Incorrect posted batch: request a Repackaging Batch reversal using batch ID '.$id.'. Reverse dependent completions/releases first.</p></div>';
 }
 return;
}
if(can_action('repack_stage')){
 $options=[];$q=db()->query('SELECT n.*,p.name,p.master_sku FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.qty>0 AND n.reversed_by_request IS NULL AND p.active=1 ORDER BY n.id DESC');foreach($q as $n){$remaining=max(0,(int)$n['qty']-release_total($n['id']));if(!$remaining||repack_active_source($n['id']))continue;$options[]=['value'=>'NS-'.$n['id'],'key'=>'NS:'.$n['id'],'label'=>'NS-'.$n['id'].' | '.$n['master_sku'].' | '.$n['name'].' | '.$n['condition_type'].' | '.$remaining.' pcs | '.$n['order_id']];}
 $stockSql='SELECT p.id,p.name,p.master_sku,COALESCE(b.qty,0)+COALESCE(i.qty,0)-COALESCE(o.qty,0)-COALESCE(n.qty,0) sellable FROM products p LEFT JOIN beginning_balances b ON b.product_id=p.id LEFT JOIN (SELECT product_id,SUM(qty) qty FROM inflows GROUP BY product_id) i ON i.product_id=p.id LEFT JOIN (SELECT product_id,SUM(qty) qty FROM outflows GROUP BY product_id) o ON o.product_id=p.id LEFT JOIN (SELECT product_id,SUM(qty) qty FROM non_sellable WHERE sellable_deducted=1 GROUP BY product_id) n ON n.product_id=p.id WHERE p.active=1 HAVING sellable>0 ORDER BY p.name';
 foreach(db()->query($stockSql) as $p)$options[]=['key'=>'ST:'.$p['id'],'label'=>'Sellable | '.$p['master_sku'].' | '.$p['name'].' | '.$p['sellable'].' pcs'];
 ?><div class="card"><h3>Create Repackaging Batch</h3><p>Select already-recorded sources. “Returns” identifies the batch origin; it does not record another return or add physical stock.</p><form method="post" action="actions.php" class="stack" id="repackForm"><?php repack_fields('repack_stage');?><input type="hidden" name="batch_ref" value="<?=e('RP-'.date('Ymd-His').'-'.bin2hex(random_bytes(6)))?>"><div class="grid two"><label>Date<input type="date" name="txn_date" value="<?=date('Y-m-d')?>" required></label><label>Source<select name="source_name"><option>Returns</option><option>Existing Warehouse Stock</option><option>RAW / For Packaging</option><option>Other Restricted Stocks</option></select></label><label>Source / Internal Batch Reference<input name="reference_no" maxlength="100" required></label><label>Responsible Person<select name="owner_id" required><?php foreach($owners as $o):?><option value="<?=(int)$o['id']?>" <?=(int)$o['id']===(int)current_user()['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label>Target Completion Date<input type="date" name="due_date"></label><label>Remarks<textarea name="reason" required></textarea></label></div><div class="table-wrap"><table class="table"><thead><tr><th>Product / Existing Stock Source</th><th>Quantity (pcs)</th><th>Classification</th><th></th></tr></thead><tbody id="repackLines"></tbody></table></div><p class="muted small">Existing packaging sources must use their full remaining quantity when grouped; Ready for Sale can be partial afterward. Other restricted sources may be partially reclassified. Sellable sources automatically remove allocations from the platform with the most available stock first; review the exact split before Submit.</p><div class="modal-actions"><button type="button" class="btn ghost" id="repackAdd">＋ Add Product</button><button class="btn primary">Review Batch</button></div></form></div>
 <template id="repackLine"><tr><td><label>Existing Source<select data-field="source" required><option value="">Select existing product / source record...</option><?php foreach($options as $o):?><option value="<?=e($o['key'])?>"><?=e($o['label'])?></option><?php endforeach;?></select></label></td><td><label>Quantity<input data-field="qty" type="number" min="1" step="1" required></label></td><td>For Repackaging</td><td><button type="button" class="btn ghost" data-remove>Remove</button></td></tr></template><script src="assets/repackaging_batch.js"></script>
 <?php
}
$term=trim($_GET['q']??'');$all=($_GET['history']??'')==='all';$offset=$all?max(0,(int)($_GET['offset']??0)):0;$where='';$args=[];if($term!==''){$where=' WHERE b.batch_ref LIKE ? OR b.reference_no LIKE ? OR b.source_name LIKE ? OR EXISTS(SELECT 1 FROM repackaging_batch_lines l JOIN products p ON p.id=l.product_id WHERE l.batch_id=b.id AND (p.name LIKE ? OR p.master_sku LIKE ?))';$args=array_fill(0,5,'%'.$term.'%');}$q=db()->prepare('SELECT b.*,u.name creator FROM repackaging_batches b LEFT JOIN users u ON u.id=b.created_by'.$where.' ORDER BY b.id DESC LIMIT '.($all?51:10).' OFFSET '.$offset);$q->execute($args);$batches=$q->fetchAll();$more=$all&&count($batches)>50;if($more)array_pop($batches);
?><div class="card"><form class="inline-form"><input type="hidden" name="page" value="repackaging_batch"><input name="q" value="<?=e($term)?>" placeholder="Search batch, reference, source or posted product..."><button class="btn secondary">Search</button><a class="btn ghost" href="?page=repackaging_batch">Clear Filters</a></form></div><div class="card table-wrap"><div class="card-head"><h3><?=$all?'Batch History':'Recent Batches (10)'?></h3><a class="btn ghost" href="?page=repackaging_batch<?=!$all?'&history=all':''?>&q=<?=urlencode($term)?>"><?=$all?'Recent':'View all'?></a></div><table class="table"><tr><th>Batch / Date</th><th>Source / Reference</th><th>Entered By</th><th>Posting Status</th><th></th></tr><?php foreach($batches as $b):?><tr><td><?=e($b['batch_ref'])?><br><?=e($b['txn_date'])?></td><td><?=e($b['source_name'])?><br><?=e($b['reference_no'])?></td><td><?=e($b['creator'])?></td><td><?=e($b['status'])?></td><td><a class="btn ghost sm" href="?page=repackaging_batch&id=<?=(int)$b['id']?>">Open Batch</a></td></tr><?php endforeach;?><?php if(!$batches):?><tr><td colspan="5">No batches found.</td></tr><?php endif;?></table><?php if($all)echo rs8_pagination(rs8_list_total('SELECT COUNT(*) FROM repackaging_batches b'.$where,$args),$offset,50,array_replace($_GET,['page'=>'repackaging_batch','history'=>'all','q'=>$term]));?></div>
